// @ts-ignore
export * from "./peer.js";
// @ts-ignore
import * as peer from "./peer.js";
// @ts-ignore
import * as rpc from "../rpc/mod.js";
// @ts-ignore
import * as mux from "../mux/mod.js";
// @ts-ignore
import * as websocket from "../transport/websocket.js";
// @ts-ignore
// import * as iframe from "../transport/iframe.ts";
export var options = {
    transport: websocket,
};
export async function connect(addr, codec) {
    const conn = await options.transport.connect(addr);
    return open(conn, codec);
}
export function open(conn, codec, handlers) {
    // if (conn === window.parent) {
    //   conn = new iframe.Conn();
    // }
    // if (typeof(conn) === "string") {
    //   conn = new iframe.Conn(document.querySelector(`iframe#${conn}`) as HTMLIFrameElement);
    // }
    const sess = new mux.Session(conn);
    const p = new peer.Peer(sess, codec);
    if (handlers) {
        for (const name in handlers) {
            p.handle(name, rpc.HandlerFunc(handlers[name]));
        }
        p.respond();
    }
    return p;
}
